export function evaluate({ inputs, time }) {
 const g = 9.8, u = inputs.launchSpeed;
 const T = 2 * u / g, ta = u / g;
 const t = Math.min(Math.max(time, 0), T);
 const v = u - g * t;
 const h = u * t - g * t * t / 2;
 const apexH = u * u / (2 * g);
 const base = 380, ppm = 240;
 const y = base - h * ppm;
 const eps = 0.005;
 const st = Math.abs(t - ta) < 0.004 ? 'Still for an instant' : (v > 0 ? 'Moving up' : 'Moving down');
 const objs = [];
 objs.push(...sdk.panel({ x: 20, y: 40, w: 600, h: 360, title: 'Tossed ball', state: st, id: 'lane.toss' }));
 objs.push(sdk.axis('axis.h', { x: 90, y: base, length: 5 * 240 * 0.3 * 0 + 300, orientation: 'y', min: 0, max: 1.25, ticks: [0, 0.25, 0.5, 0.75, 1, 1.25], label: 'Height', unit: 'm' }));
 objs.push(sdk.line('guide.launch', 100, base, 400, base, { role: 'neutral' }));
 const cx = 260;
 objs.push(sdk.circle('ball.toss', cx, y - 14, 28, { role: 'observed' }));
 const sc = 14;
 objs.push(...sdk.vector('vec.v', { x: cx + 40, y: y - 14 }, { value: v, direction: 'up' }, { scale: sc, label: 'v', role: 'input' }));
 objs.push(...sdk.vector('vec.a', { x: cx - 40, y: y - 14 }, { value: -g, direction: 'up' }, { scale: 6, label: 'a', role: 'warning' }));
 objs.push(...sdk.callout(cx + 90, y - 30, [st, 'Gravity pulls down'], { id: 'callout.toss' }));
 return { frame: { width: 640, height: 420, objects: objs, readouts: [{ id: 'motionState', value: st }, { id: 'gravityState', value: 'Gravity pulls down' }] }, quantities: { launchSpeed: u, gravity: g, apexTime: ta, apexHeight: apexH, velocity: v, height: h } };
}
